export function nativeMpegLayerOneFixture(): Readonly<{ file: File; channels: readonly Float32Array[] }> {
	const bytes = Uint8Array.from(inflateSync(Buffer.from(ENCODED, 'base64')));
	assert.equal(createHash('sha256').update(bytes).digest('hex'), '8bffe46c1a1ba709b35f4782c1a661d0081e8ef84222edcf518ee5e4c2e77f13');
	const reference = inflateSync(Buffer.from(REFERENCE, 'base64'));
	assert.equal(createHash('sha256').update(reference).digest('hex'), '61ee45d668498a47cfc3c41ff19c27ea026235a966e6520b6e50f13b00525c20');
	assert.equal(reference.length, 18_816 * 2 * 4);
	return { file: new File([bytes], 'Recording.mp1', { type: 'audio/mpeg' }),
		channels: [0, 1].map(channel => Float32Array.from({ length: 18_816 }, (_, frame) => reference.readFloatLE((frame * 2 + channel) * 4))) };
}
